"use client";

import * as React from "react";
import {
  ArrowUp,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Search,
  X,
} from "lucide-react";
import { NumberRoll } from "./number-roll";
import { PillSelect, type PillOption } from "./imported-pill-select";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import { useRowMotion } from "./use-row-motion";

/* ─────────────────────────────────────────────────────────
 * DATA TABLE: rows that travel
 *
 *   sort      click a header and every row glides to its new
 *             rank, top first; rows that didn't move stay put;
 *             the arrow flips with a slight overshoot
 *   live      new data re-sorts itself: a row whose amount
 *             grows glides past the ones above it, new rows
 *             fade in as the rows below make room
 *   search    rows that stop matching fold away, the rest close
 *             up, and "248 payments" rolls down to the count
 *   select    tick a row and the toolbar becomes the selection
 *             ("3 selected · Export · Delete"); Shift ticks a
 *             range one row after another
 *   remove    rows fold out and the toolbar holds "3 deleted ·
 *             Undo" over a draining thin line before it commits
 *   detail    a row opens into its detail by measured height
 *   edit      double-click a cell (or Enter on it) to edit in
 *             place; it saves with a check, or shakes back
 *   pages     the next page slides in from the side you went;
 *             "11–20 of 248" rolls
 *
 * Narrow containers get one card per row instead of columns.
 * ───────────────────────────────────────────────────────── */

export type DataTableValue = string | number | Date | null | undefined;

export interface DataTableColumn<T> {
  key: string;
  header: string;
  /** What the column sorts, searches and edits by. Defaults to row[key]. */
  value?: (row: T) => DataTableValue;
  /** What the cell shows. Defaults to the value as text. */
  cell?: (row: T) => React.ReactNode;
  align?: "left" | "right";
  /** A grid track, e.g. "minmax(0,1.6fr)" or "120px". */
  width?: string;
  sortable?: boolean;
  /** Search looks in this column. */
  searchable?: boolean;
  /** Double-click or Enter edits it in place (needs onEdit). */
  editable?: boolean;
  /** Its place in the card a narrow container shows instead of columns. */
  card?: "title" | "subtitle" | "trailing" | "hidden";
}

export interface DataTableAction<T> {
  id: string;
  label: string;
  /** Labels while it runs and once it's done, e.g. ["Exporting", "Exported"]. */
  progress?: [string, string];
  tone?: "default" | "destructive";
  /** The rows leave at once and the toolbar offers Undo; run() is called when the chance to undo is over. */
  removes?: boolean;
  run: (rows: T[]) => Promise<void> | void;
}

export type DataTableSort = { key: string; dir: "asc" | "desc" };

export interface DataTableProps<T> extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> {
  columns: DataTableColumn<T>[];
  rows: T[];
  /** Defaults to row.id. */
  getRowId?: (row: T) => string;
  /** How a row is named when announced; defaults to its first column. */
  rowLabel?: (row: T) => string;
  /** What a row is called: ["payment", "payments"]. */
  noun?: [string, string];
  sort?: DataTableSort | null;
  defaultSort?: DataTableSort | null;
  onSortChange?: (sort: DataTableSort | null) => void;
  /** Shows the search field; it looks in columns marked searchable (or all, if none are). */
  searchable?: boolean;
  searchPlaceholder?: string;
  selectable?: boolean;
  selected?: string[];
  defaultSelected?: string[];
  onSelectedChange?: (ids: string[]) => void;
  /** What the toolbar offers for the selected rows. */
  actions?: DataTableAction<T>[];
  /** How long Undo is offered after a removing action, ms. */
  undoFor?: number;
  /** Saves an edited cell. Throw to put the old value back. */
  onEdit?: (row: T, key: string, value: string) => Promise<void> | void;
  /** Rows open into this. */
  renderDetail?: (row: T) => React.ReactNode;
  pageSize?: number;
  label?: string;
}

type Undo<T> = {
  key: number;
  ids: string[];
  rows: T[];
  action: DataTableAction<T>;
};
type Cursor = { id: string; col: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const CELL_FOCUS =
  "outline-none focus-visible:shadow-[inset_0_0_0_1.5px_var(--ring)]";
const NO_IDS: string[] = [];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const swap = (
  on: boolean,
  reduced: boolean,
  from = 8,
): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : `translateY(${from}px)`,
  filter: on ? "none" : "blur(4px)",
  transition: reduced
    ? "none"
    : `opacity 240ms ${EASE}, transform 420ms ${EASE}, filter 240ms ${EASE}`,
  pointerEvents: on ? undefined : "none",
});

const compare = (a: DataTableValue, b: DataTableValue) => {
  if (a == null && b == null) return 0;
  if (a == null) return 1;
  if (b == null) return -1;
  if (a instanceof Date && b instanceof Date) return a.getTime() - b.getTime();
  if (typeof a === "number" && typeof b === "number") return a - b;
  return String(a).localeCompare(String(b), undefined, {
    numeric: true,
    sensitivity: "base",
  });
};

/** A checkbox that draws: the check (or the dash, for some) strokes itself in. */
function Box({
  state,
  reduced,
  delay = 0,
}: {
  state: "on" | "off" | "some";
  reduced: boolean;
  delay?: number;
}) {
  const t = (on: boolean) =>
    reduced
      ? "none"
      : `stroke-dashoffset ${on ? 300 : 120}ms ${EASE} ${on ? delay + 60 : 0}ms`;
  return (
    <span
      aria-hidden="true"
      className="relative flex size-4 items-center justify-center rounded-[5px] transition-[background-color,box-shadow] duration-200"
      style={{
        background: state === "off" ? "var(--background)" : "var(--primary)",
        boxShadow:
          state === "off"
            ? "inset 0 0 0 1px color-mix(in oklab, var(--foreground) 28%, transparent)"
            : "none",
        transitionDelay: state === "off" ? "0ms" : `${delay}ms`,
      }}
    >
      <svg
        viewBox="0 0 16 16"
        className="absolute size-3 text-primary-foreground"
        fill="none"
      >
        <path
          d="M3.5 8.5 6.5 11.5 12.5 4.5"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          pathLength={1}
          strokeDasharray={1}
          style={{
            strokeDashoffset: state === "on" ? 0 : 1,
            transition: t(state === "on"),
          }}
        />
        <path
          d="M4 8h8"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          pathLength={1}
          strokeDasharray={1}
          style={{
            strokeDashoffset: state === "some" ? 0 : 1,
            transition: t(state === "some"),
          }}
        />
      </svg>
    </span>
  );
}

const cellValue = <T,>(c: DataTableColumn<T>, row: T): DataTableValue =>
  c.value
    ? c.value(row)
    : ((row as Record<string, unknown>)[c.key] as DataTableValue);
const cellText = <T,>(c: DataTableColumn<T>, row: T): React.ReactNode =>
  c.cell ? c.cell(row) : String(cellValue(c, row) ?? "");

type RowActions<T> = {
  toggle: (id: string, range: boolean) => void;
  toggleOpen: (id: string, row: T) => void;
  cursor: (c: Cursor) => void;
  edit: (e: { id: string; key: string }) => void;
  finish: (row: T, key: string, value: string | null) => void;
  detail: (row: T) => React.ReactNode;
};

type RowProps<T> = {
  row: T;
  id: string;
  index: number;
  columns: DataTableColumn<T>[];
  tracks: string;
  selectable: boolean;
  canEdit: boolean;
  hasDetail: boolean;
  isSelected: boolean;
  isOpen: boolean;
  /** When its tick draws, in a range selection. */
  delay: number;
  /** The focused cell in this row (-1: the row itself), or null. */
  focusCol: number | null;
  rowTab: 0 | -1;
  editingKey: string | null;
  drafts: ReadonlyMap<string, { value: string; status: "pending" | "done" }>;
  reduced: boolean;
  name: string;
  actions: React.RefObject<RowActions<T>>;
};

/** One row, memoised on plain values: a sort, a selection or a keystroke re-renders only the rows it changes. */
function TableRowView<T>(p: RowProps<T>) {
  const { row, id, columns, reduced, actions: a } = p;
  const editable = (c: DataTableColumn<T>) => !!(c.editable && p.canEdit);
  const title = columns.find((c) => c.card === "title") ?? columns[0];
  const subtitles = columns.filter((c) => c.card === "subtitle");
  const trailing = columns.filter((c) => c.card === "trailing");

  const cell = (col: DataTableColumn<T>) => {
    const draft = p.drafts.get(`${id}:${col.key}`);
    if (p.editingKey === col.key)
      return (
        <input
          autoFocus
          defaultValue={String(cellValue(col, row) ?? "")}
          aria-label={`${col.header} for ${p.name}`}
          onFocus={(e) => e.currentTarget.select()}
          onKeyDown={(e) => {
            e.stopPropagation();
            if (e.key === "Enter")
              a.current.finish(row, col.key, e.currentTarget.value);
            if (e.key === "Escape") a.current.finish(row, col.key, null);
          }}
          onBlur={(e) => a.current.finish(row, col.key, e.currentTarget.value)}
          className={`-mx-1.5 h-8 w-[calc(100%+12px)] min-w-0 rounded-[8px] bg-background px-1.5 text-[13px] shadow-[inset_0_0_0_1.5px_var(--ring)] outline-none [@media(pointer:coarse)]:text-[16px] ${col.align === "right" ? "text-right" : ""}`}
        />
      );
    return (
      <span
        className={`flex min-w-0 items-center gap-1.5 ${col.align === "right" ? "justify-end" : ""}`}
      >
        <span className="min-w-0 truncate">
          {draft ? (
            <TextMorph animateWidth={false}>{draft.value}</TextMorph>
          ) : (
            cellText(col, row)
          )}
        </span>
        {draft && (
          <span className="relative size-3.5 shrink-0" aria-hidden="true">
            <span
              className="absolute inset-0 flex items-center justify-center"
              style={swap(draft.status === "pending", reduced, 0)}
            >
              <span className="size-3 rounded-full border-[1.5px] border-muted-foreground border-t-transparent motion-safe:animate-spin" />
            </span>
            <svg
              viewBox="0 0 16 16"
              className="absolute inset-0 size-3.5 text-emerald-600 dark:text-emerald-400"
              fill="none"
              style={{
                opacity: draft.status === "done" ? 1 : 0,
                transition: `opacity 200ms ${EASE}`,
              }}
            >
              <path
                d="M3.5 8.5 6.5 11.5 12.5 4.5"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
                pathLength={1}
                strokeDasharray={1}
                style={{
                  strokeDashoffset: draft.status === "done" ? 0 : 1,
                  transition: reduced
                    ? "none"
                    : `stroke-dashoffset 380ms ${EASE} 80ms`,
                }}
              />
            </svg>
          </span>
        )}
      </span>
    );
  };

  return (
    <div
      data-row-id={id}
      role="row"
      aria-rowindex={p.index}
      aria-selected={p.selectable ? p.isSelected : undefined}
      aria-expanded={p.hasDetail ? p.isOpen : undefined}
      tabIndex={p.rowTab}
      onFocus={(e) =>
        e.target === e.currentTarget && a.current.cursor({ id, col: -1 })
      }
      className={`relative border-b border-border transition-colors duration-200 last:border-b-0 ${CELL_FOCUS}`}
      style={{
        background: p.isSelected
          ? "color-mix(in oklab, var(--primary) 5%, var(--background))"
          : "var(--background)",
      }}
    >
      {/* Columns, wide */}
      <div
        className="grid min-h-12 items-center @max-[34rem]:hidden"
        style={{ gridTemplateColumns: p.tracks }}
      >
        {p.selectable && (
          <span role="gridcell" className="flex items-center justify-center">
            <button
              type="button"
              tabIndex={-1}
              aria-label={`Select ${p.name}`}
              aria-pressed={p.isSelected}
              onClick={(e) => a.current.toggle(id, e.shiftKey)}
              className="flex size-8 cursor-pointer items-center justify-center rounded-[8px] hover:bg-accent"
            >
              <Box
                state={p.isSelected ? "on" : "off"}
                reduced={reduced}
                delay={p.delay}
              />
            </button>
          </span>
        )}
        {columns.map((col, ci) => (
          <span
            key={col.key}
            role="gridcell"
            data-col-key={col.key}
            data-col-index={ci}
            tabIndex={p.focusCol === ci ? 0 : -1}
            onFocus={() => a.current.cursor({ id, col: ci })}
            onDoubleClick={() =>
              editable(col) && a.current.edit({ id, key: col.key })
            }
            className={`min-w-0 rounded-[6px] px-3 py-2 text-[13px] ${col.align === "right" ? "text-right tabular-nums" : ""} ${editable(col) ? "cursor-text" : ""} ${CELL_FOCUS}`}
          >
            {cell(col)}
          </span>
        ))}
        {p.hasDetail && (
          <span role="gridcell" className="flex items-center justify-center">
            <button
              type="button"
              tabIndex={-1}
              aria-label={`${p.isOpen ? "Close" : "Open"} ${p.name}`}
              aria-expanded={p.isOpen}
              onClick={() => a.current.toggleOpen(id, row)}
              className="flex size-8 cursor-pointer items-center justify-center rounded-[8px] text-muted-foreground hover:bg-accent hover:text-foreground"
            >
              <ChevronDown
                className="size-4"
                strokeWidth={1.75}
                style={{
                  transform: p.isOpen ? "rotate(180deg)" : "none",
                  transition: reduced ? "none" : `transform 420ms ${THROW}`,
                }}
              />
            </button>
          </span>
        )}
      </div>

      {/* One card, narrow */}
      <div
        className="hidden min-h-[60px] items-center gap-3 py-2.5 pr-3 @max-[34rem]:flex"
        style={{ paddingLeft: p.selectable ? 0 : 12 }}
      >
        {p.selectable && (
          <button
            type="button"
            tabIndex={-1}
            aria-label={`Select ${p.name}`}
            aria-pressed={p.isSelected}
            onClick={(e) => a.current.toggle(id, e.shiftKey)}
            className="flex size-10 shrink-0 cursor-pointer items-center justify-center"
          >
            <Box
              state={p.isSelected ? "on" : "off"}
              reduced={reduced}
              delay={p.delay}
            />
          </button>
        )}
        <button
          type="button"
          tabIndex={-1}
          disabled={!p.hasDetail}
          onClick={() => p.hasDetail && a.current.toggleOpen(id, row)}
          className="flex min-w-0 flex-1 cursor-pointer items-center gap-3 text-left disabled:cursor-default"
        >
          <span className="min-w-0 flex-1">
            <span className="block truncate text-[13.5px] font-medium">
              {cellText(title, row)}
            </span>
            {subtitles.length > 0 && (
              <span className="mt-0.5 flex min-w-0 items-center gap-1.5 truncate text-[12px] text-muted-foreground">
                {subtitles.map((c, i) => (
                  <React.Fragment key={c.key}>
                    {i > 0 && <span aria-hidden="true">·</span>}
                    <span className="truncate">{cellText(c, row)}</span>
                  </React.Fragment>
                ))}
              </span>
            )}
          </span>
          {trailing.length > 0 && (
            <span className="flex shrink-0 flex-col items-end gap-1 text-[13px] tabular-nums">
              {trailing.map((c) => (
                <span key={c.key}>{cellText(c, row)}</span>
              ))}
            </span>
          )}
        </button>
      </div>

      {/* Detail: the row opens by its own measured height. */}
      {p.hasDetail && (
        <div
          className="grid transition-[grid-template-rows] duration-[420ms]"
          style={{
            gridTemplateRows: p.isOpen ? "1fr" : "0fr",
            transitionTimingFunction: EASE,
          }}
          inert={!p.isOpen}
        >
          <div className="min-h-0 overflow-hidden">
            <div
              className="border-t border-dashed border-border px-3 pb-4 pt-3"
              style={{
                paddingLeft: p.selectable ? 52 : 12,
                opacity: p.isOpen ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `opacity 300ms ${EASE} ${p.isOpen ? 120 : 0}ms`,
              }}
            >
              {a.current?.detail(row)}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const TableRow = React.memo(TableRowView) as typeof TableRowView;

export function DataTable<T>({
  columns,
  rows,
  getRowId = (row) => String((row as { id?: unknown }).id),
  rowLabel,
  noun = ["row", "rows"],
  sort: sortProp,
  defaultSort = null,
  onSortChange,
  searchable = true,
  searchPlaceholder = "Search",
  selectable = false,
  selected: selectedProp,
  defaultSelected = NO_IDS,
  onSelectedChange,
  actions = [],
  undoFor = 5000,
  onEdit,
  renderDetail,
  pageSize = 10,
  label = "Table",
  className = "",
  ...props
}: DataTableProps<T>) {
  const reduced = useReducedMotion();
  const uid = React.useId();
  const [sortOwn, setSortOwn] = React.useState<DataTableSort | null>(
    defaultSort,
  );
  const sort = sortProp === undefined ? sortOwn : sortProp;
  const [selectedOwn, setSelectedOwn] =
    React.useState<string[]>(defaultSelected);
  const selectedIds = selectedProp ?? selectedOwn;
  const selected = React.useMemo(() => new Set(selectedIds), [selectedIds]);
  const [query, setQuery] = React.useState("");
  const [page, setPage] = React.useState(0);
  const [pageDir, setPageDir] = React.useState(0);
  const [hidden, setHidden] = React.useState<ReadonlySet<string>>(
    () => new Set(),
  );
  const [undo, setUndo] = React.useState<Undo<T> | null>(null);
  const [open, setOpen] = React.useState<ReadonlySet<string>>(() => new Set());
  const [editing, setEditingState] = React.useState<{
    id: string;
    key: string;
  } | null>(null);
  // Enter and the blur that follows it both finish an edit; only the first counts.
  const editingRef = React.useRef<{ id: string; key: string } | null>(null);
  const setEditing = (e: { id: string; key: string } | null) => {
    editingRef.current = e;
    setEditingState(e);
  };
  const [drafts, setDrafts] = React.useState<
    ReadonlyMap<string, { value: string; status: "pending" | "done" }>
  >(() => new Map());
  const [actionStatus, setActionStatus] = React.useState<
    Record<string, ActionStatus>
  >({});
  const [notice, setNotice] = React.useState<{
    text: string;
    key: number;
  } | null>(null);
  const [announce, setAnnounce] = React.useState("");
  const [cursor, setCursor] = React.useState<Cursor | null>(null);
  const [cascade, setCascade] = React.useState<{
    ids: string[];
    key: number;
  } | null>(null);
  const [holdUndo, setHoldUndo] = React.useState(false);
  const anchor = React.useRef<string | null>(null);
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const gridRef = React.useRef<HTMLDivElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);
  const seq = React.useRef(0);

  const name = (row: T) =>
    rowLabel?.(row) ?? String(valueOf(columns[0], row) ?? getRowId(row));
  const valueOf = cellValue;
  const count = (n: number) => `${n === 1 ? noun[0] : noun[1]}`;
  const say = (text: string) =>
    setAnnounce((a) => (a === text ? `${text} ` : text));
  const flash = (text: string) => {
    const key = ++seq.current;
    setNotice({ text, key });
    window.setTimeout(
      () => setNotice((n) => (n?.key === key ? null : n)),
      3600,
    );
  };

  const setSelected = (next: string[]) => {
    if (selectedProp === undefined) setSelectedOwn(next);
    onSelectedChange?.(next);
  };

  // ── Rows in view ───────────────────────────────────────
  const searchCols = columns.some((c) => c.searchable)
    ? columns.filter((c) => c.searchable)
    : columns;
  const q = query.trim().toLowerCase();
  const visible = rows.filter((r) => !hidden.has(getRowId(r)));
  const matched = q
    ? visible.filter((r) =>
        searchCols.some((c) =>
          String(valueOf(c, r) ?? "")
            .toLowerCase()
            .includes(q),
        ),
      )
    : visible;
  const sortCol = sort ? columns.find((c) => c.key === sort.key) : undefined;
  const sorted = sortCol
    ? [...matched].sort(
        (a, b) =>
          compare(valueOf(sortCol, a), valueOf(sortCol, b)) *
          (sort!.dir === "asc" ? 1 : -1),
      )
    : matched;
  const pages = Math.max(1, Math.ceil(sorted.length / pageSize));
  const current = Math.min(page, pages - 1);
  const pageRows = sorted.slice(
    current * pageSize,
    current * pageSize + pageSize,
  );

  const ranks = new Map(sorted.map((r, i) => [getRowId(r), i]));
  const motion = useRowMotion(bodyRef, {
    reduced,
    resetKey: current,
    ranks,
    ghosts: ghostRef,
  });

  // A new page slides in from the side you went toward.
  const shownPage = React.useRef(current);
  React.useLayoutEffect(() => {
    if (shownPage.current === current) return;
    const dir = Math.sign(current - shownPage.current) || pageDir;
    shownPage.current = current;
    if (reduced) return;
    bodyRef.current?.animate(
      [
        {
          transform: `translateX(${dir * 28}px)`,
          opacity: 0,
          filter: "blur(4px)",
        },
        { transform: "none", opacity: 1, filter: "blur(0px)" },
      ],
      { duration: 440, easing: EASE },
    );
  }, [current, pageDir, reduced]);

  // The list's height eases to fit, so rows folding away or arriving never make the page jump.
  React.useLayoutEffect(() => {
    const wrap = wrapRef.current;
    const body = bodyRef.current;
    if (!wrap || !body) return;
    const fit = () => {
      const h = `${body.offsetHeight}px`;
      if (wrap.style.height === h) return;
      wrap.style.transition =
        wrap.dataset.ready && !reduced ? `height 420ms ${EASE}` : "none";
      wrap.style.height = h;
      wrap.dataset.ready = "1";
    };
    fit();
    const observer = new ResizeObserver(fit);
    observer.observe(body);
    return () => observer.disconnect();
  }, [reduced]);

  // ── Sorting ────────────────────────────────────────────
  const sortBy = (key: string) => {
    const col = columns.find((c) => c.key === key)!;
    const sample = rows.map((r) => valueOf(col, r)).find((v) => v != null);
    const firstDir =
      typeof sample === "number" || sample instanceof Date ? "desc" : "asc";
    const next: DataTableSort | null =
      sort?.key !== key
        ? { key, dir: firstDir }
        : { key, dir: sort.dir === "asc" ? "desc" : "asc" };
    motion.stagger();
    if (sortProp === undefined) setSortOwn(next);
    onSortChange?.(next);
    say(
      `Sorted by ${col.header}, ${next.dir === "asc" ? "ascending" : "descending"}.`,
    );
  };

  // ── Selection ──────────────────────────────────────────
  const toggle = (id: string, range: boolean) => {
    const ids = sorted.map(getRowId);
    if (range && anchor.current && ids.includes(anchor.current)) {
      const a = ids.indexOf(anchor.current);
      const b = ids.indexOf(id);
      const span = ids.slice(Math.min(a, b), Math.max(a, b) + 1);
      const on = !selected.has(id);
      const next = new Set(selected);
      span.forEach((x) => (on ? next.add(x) : next.delete(x)));
      // Ticks run down the range one after another, from the anchor.
      setCascade({
        ids: a <= b ? span : [...span].reverse(),
        key: ++seq.current,
      });
      setSelected([...next]);
      say(`${next.size} selected.`);
    } else {
      const next = new Set(selected);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setCascade(null);
      setSelected([...next]);
      say(`${next.size ? `${next.size} selected` : "Selection cleared"}.`);
    }
    anchor.current = id;
  };
  const allIds = sorted.map(getRowId);
  const allState: "on" | "off" | "some" =
    allIds.length && allIds.every((i) => selected.has(i))
      ? "on"
      : allIds.some((i) => selected.has(i))
        ? "some"
        : "off";
  const toggleAll = () => {
    setCascade(
      allState === "on"
        ? null
        : { ids: pageRows.map(getRowId), key: ++seq.current },
    );
    setSelected(allState === "on" ? [] : allIds);
    say(
      allState === "on" ? "Selection cleared." : `${allIds.length} selected.`,
    );
  };

  // ── Actions ────────────────────────────────────────────
  const run = async (action: DataTableAction<T>) => {
    const chosen = rows.filter((r) => selected.has(getRowId(r)));
    if (!chosen.length) return;
    if (action.removes) {
      const ids = chosen.map(getRowId);
      // Commit whatever was waiting before this one takes the toolbar.
      if (undo) commitUndo(undo);
      setHidden((h) => new Set([...h, ...ids]));
      setSelected([]);
      setUndo({ key: ++seq.current, ids, rows: chosen, action });
      say(
        `${ids.length} ${count(ids.length)} ${action.progress?.[1]?.toLowerCase() ?? "removed"}. Undo is available.`,
      );
      return;
    }
    setActionStatus((s) => ({ ...s, [action.id]: "pending" }));
    try {
      await action.run(chosen);
      setActionStatus((s) => ({ ...s, [action.id]: "success" }));
      say(
        `${action.progress?.[1] ?? "Done"}: ${chosen.length} ${count(chosen.length)}.`,
      );
    } catch {
      setActionStatus((s) => ({ ...s, [action.id]: "error" }));
      say(`${action.label} failed.`);
    }
  };

  const commitUndo = async (u: Undo<T>) => {
    setUndo((cur) => (cur?.key === u.key ? null : cur));
    try {
      await u.action.run(u.rows);
    } catch {
      setHidden((h) => {
        const n = new Set(h);
        u.ids.forEach((i) => n.delete(i));
        return n;
      });
      flash(
        `Couldn't ${u.action.label.toLowerCase()} ${u.ids.length} ${count(u.ids.length)}. They're back.`,
      );
      say(`${u.action.label} failed. The rows are back.`);
    }
  };

  const takeBack = () => {
    if (!undo) return;
    setHidden((h) => {
      const n = new Set(h);
      undo.ids.forEach((i) => n.delete(i));
      return n;
    });
    setUndo(null);
    say(`Undone. ${undo.ids.length} ${count(undo.ids.length)} back.`);
  };

  // ── Editing ────────────────────────────────────────────
  const finishEdit = async (row: T, key: string, value: string | null) => {
    const id = getRowId(row);
    if (editingRef.current?.id !== id || editingRef.current.key !== key) return;
    setEditing(null);
    const cellKey = `${id}:${key}`;
    requestAnimationFrame(() =>
      gridRef.current
        ?.querySelector<HTMLElement>(
          `[data-row-id="${CSS.escape(id)}"] [data-col-key="${CSS.escape(key)}"]`,
        )
        ?.focus({ preventScroll: true }),
    );
    const col = columns.find((c) => c.key === key)!;
    if (value === null || value === String(valueOf(col, row) ?? "") || !onEdit)
      return;
    setDrafts((d) => new Map(d).set(cellKey, { value, status: "pending" }));
    try {
      await onEdit(row, key, value);
      setDrafts((d) => new Map(d).set(cellKey, { value, status: "done" }));
      say(`Saved ${col.header.toLowerCase()}.`);
      window.setTimeout(
        () =>
          setDrafts((d) => {
            const n = new Map(d);
            if (n.get(cellKey)?.status === "done") n.delete(cellKey);
            return n;
          }),
        1400,
      );
    } catch {
      setDrafts((d) => {
        const n = new Map(d);
        n.delete(cellKey);
        return n;
      });
      if (!reduced)
        gridRef.current
          ?.querySelector<HTMLElement>(
            `[data-row-id="${CSS.escape(id)}"] [data-col-key="${CSS.escape(key)}"]`,
          )
          ?.animate(
            [
              { transform: "none" },
              { transform: "translateX(-4px)" },
              { transform: "translateX(4px)" },
              { transform: "translateX(-2px)" },
              { transform: "none" },
            ],
            { duration: 380, easing: "ease-out" },
          );
      flash(`Couldn't save ${col.header.toLowerCase()} for ${name(row)}.`);
      say(`Couldn't save. ${col.header} is back to what it was.`);
    }
  };

  // ── Pages ──────────────────────────────────────────────
  const goPage = (dir: number) => {
    const next = Math.max(0, Math.min(pages - 1, current + dir));
    if (next === current) return;
    setPageDir(dir);
    setPage(next);
    setCursor(null);
    say(`Page ${next + 1} of ${pages}.`);
  };

  // ── Keys: rows, then cells ─────────────────────────────
  const editable = (c: DataTableColumn<T>) => !!(c.editable && onEdit);
  const focusAt = (c: Cursor) => {
    setCursor(c);
    requestAnimationFrame(() => {
      const row = gridRef.current?.querySelector<HTMLElement>(
        `[data-row-id="${CSS.escape(c.id)}"]`,
      );
      const cell =
        c.col < 0
          ? null
          : row?.querySelector<HTMLElement>(`[data-col-index="${c.col}"]`);
      // Narrow, the cells are a card and can't take focus: the row does.
      (cell && cell.offsetParent ? cell : row)?.focus({ preventScroll: false });
    });
  };
  const onGridKey = (e: React.KeyboardEvent) => {
    if (editing || (e.target as HTMLElement).closest("input, button")) return;
    const ids = pageRows.map(getRowId);
    const c =
      cursor && ids.includes(cursor.id)
        ? cursor
        : ids.length
          ? { id: ids[0], col: -1 }
          : null;
    if (!c) return;
    const i = ids.indexOf(c.id);
    const row = pageRows[i];
    const keys: Record<string, () => void> = {
      ArrowDown: () =>
        i < ids.length - 1 && focusAt({ id: ids[i + 1], col: c.col }),
      ArrowUp: () => i > 0 && focusAt({ id: ids[i - 1], col: c.col }),
      ArrowRight: () =>
        c.col < columns.length - 1 && focusAt({ id: c.id, col: c.col + 1 }),
      ArrowLeft: () => c.col > -1 && focusAt({ id: c.id, col: c.col - 1 }),
      Home: () => focusAt({ id: ids[0], col: c.col }),
      End: () => focusAt({ id: ids[ids.length - 1], col: c.col }),
      PageDown: () => goPage(1),
      PageUp: () => goPage(-1),
      " ": () => selectable && toggle(c.id, e.shiftKey),
      Enter: () => {
        const col = columns[c.col];
        if (col && editable(col)) setEditing({ id: c.id, key: col.key });
        else if (renderDetail) toggleOpen(c.id, row);
      },
    };
    const go = keys[e.key];
    if (!go) return;
    e.preventDefault();
    go();
  };

  const toggleOpen = (id: string, row: T) => {
    setOpen((o) => {
      const n = new Set(o);
      if (n.has(id)) n.delete(id);
      else n.add(id);
      return n;
    });
    say(`${open.has(id) ? "Closed" : "Opened"} ${name(row)}.`);
  };

  // ── Render ─────────────────────────────────────────────
  const tracks = `${selectable ? "40px " : ""}${columns.map((c) => c.width ?? "minmax(0,1fr)").join(" ")}${renderDetail ? " 40px" : ""}`;
  const mode = undo ? "undo" : selected.size ? "selection" : "search";
  const from = sorted.length ? current * pageSize + 1 : 0;
  const to = Math.min(sorted.length, current * pageSize + pageSize);
  const sortable = columns.filter((c) => c.sortable);
  const sortOptions: PillOption[] = [
    { value: "", label: "Unsorted" },
    ...sortable.flatMap((c) => [
      { value: `${c.key}:asc`, label: `${c.header}, ascending` },
      { value: `${c.key}:desc`, label: `${c.header}, descending` },
    ]),
  ];

  // What the memoised rows call, through one ref, so a row never re-renders just because these were re-created.
  const rowActions = React.useRef<RowActions<T>>({
    toggle,
    toggleOpen,
    cursor: (c) => setCursor(c),
    edit: (e) => setEditing(e),
    finish: finishEdit,
    detail: (row) => renderDetail?.(row),
  });
  React.useLayoutEffect(() => {
    rowActions.current = {
      toggle,
      toggleOpen,
      cursor: (c) => setCursor(c),
      edit: (e) => setEditing(e),
      finish: finishEdit,
      detail: (row) => renderDetail?.(row),
    };
  });

  return (
    <div
      className={`@container w-full text-foreground ${className}`}
      {...props}
    >
      {/* Toolbar: one surface that is the search, the selection or the undo. */}
      <div
        onPointerEnter={() => setHoldUndo(true)}
        onPointerLeave={() => setHoldUndo(false)}
        onFocus={() => setHoldUndo(true)}
        onBlur={(e) =>
          !e.currentTarget.contains(e.relatedTarget as Node | null) &&
          setHoldUndo(false)
        }
        className="relative h-11 overflow-hidden rounded-[14px] border border-border transition-colors duration-300"
        style={{
          background:
            mode === "search"
              ? "var(--background)"
              : "color-mix(in oklab, var(--primary) 6%, var(--background))",
        }}
      >
        <div
          className="absolute inset-0 flex items-center gap-2 pl-3 pr-2"
          style={swap(mode === "search", reduced, mode === "search" ? 0 : -8)}
          inert={mode !== "search"}
        >
          {searchable ? (
            <label className="flex min-w-0 flex-1 items-center gap-2">
              <Search
                className="size-4 shrink-0 text-muted-foreground"
                strokeWidth={1.75}
                aria-hidden="true"
              />
              <input
                value={query}
                onChange={(e) => {
                  setQuery(e.target.value);
                  setPage(0);
                }}
                placeholder={searchPlaceholder}
                aria-label={searchPlaceholder}
                aria-describedby={`${uid}-count`}
                className="h-9 min-w-0 flex-1 bg-transparent text-[13.5px] outline-none placeholder:text-muted-foreground [@media(pointer:coarse)]:text-[16px]"
              />
              <button
                type="button"
                aria-label="Clear search"
                onClick={() => setQuery("")}
                className="flex size-7 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground"
                style={swap(!!query, reduced, 0)}
                tabIndex={query ? 0 : -1}
              >
                <X className="size-3.5" strokeWidth={1.75} />
              </button>
            </label>
          ) : (
            <span className="flex-1" />
          )}
          {sortable.length > 0 && (
            <span className="hidden shrink-0 @max-[34rem]:flex">
              <PillSelect
                label="Sort by"
                align="end"
                width={220}
                options={sortOptions}
                value={sort ? `${sort.key}:${sort.dir}` : ""}
                onValueChange={(v) => {
                  const [key, dir] = v.split(":");
                  const next = key ? { key, dir: dir as "asc" | "desc" } : null;
                  motion.stagger();
                  if (sortProp === undefined) setSortOwn(next);
                  onSortChange?.(next);
                }}
                // Plain text: this pill is hidden on wide tables, and a morph there would still measure every letter.
                renderValue={() => (
                  <span className="inline-flex items-center text-muted-foreground">
                    {sortCol ? sortCol.header : "Sort"}
                    <ArrowUp
                      className="ml-1 size-3"
                      strokeWidth={2}
                      aria-hidden="true"
                      style={{
                        transform:
                          sort?.dir === "desc" ? "rotate(180deg)" : "none",
                        transition: reduced
                          ? "none"
                          : `transform 420ms ${THROW}`,
                      }}
                    />
                  </span>
                )}
              />
            </span>
          )}
          <span
            id={`${uid}-count`}
            className="shrink-0 whitespace-nowrap pr-1 text-[12px] tabular-nums text-muted-foreground @max-[34rem]:hidden"
          >
            <NumberRoll value={sorted.length} />{" "}
            <TextMorph>{count(sorted.length)}</TextMorph>
          </span>
        </div>

        <div
          className="absolute inset-0 flex items-center gap-1 pl-1.5 pr-1.5"
          style={swap(
            mode === "selection",
            reduced,
            mode === "search" ? 8 : -8,
          )}
          inert={mode !== "selection"}
        >
          <button
            type="button"
            aria-label="Clear selection"
            onClick={() => setSelected([])}
            className={`flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground ${FOCUS}`}
          >
            <X className="size-4" strokeWidth={1.75} />
          </button>
          <span className="mr-auto whitespace-nowrap text-[13px] font-medium tabular-nums">
            <NumberRoll value={Math.max(1, selected.size)} /> selected
          </span>
          {actions.map((a) => (
            <StatusButton
              key={a.id}
              variant="ghost"
              size="sm"
              status={actionStatus[a.id] ?? "idle"}
              labels={{
                idle: a.label,
                pending: a.progress?.[0] ?? a.label,
                success: a.progress?.[1] ?? "Done",
                error: "Try again",
              }}
              onClick={() => run(a)}
              onReset={() => setActionStatus((s) => ({ ...s, [a.id]: "idle" }))}
              className={
                a.tone === "destructive" &&
                (actionStatus[a.id] ?? "idle") === "idle"
                  ? "!text-red-600 hover:!bg-red-500/10 dark:!text-red-400"
                  : ""
              }
            />
          ))}
        </div>

        <div
          className="absolute inset-0 flex items-center gap-2 pl-3 pr-1.5"
          style={swap(mode === "undo", reduced, 8)}
          inert={mode !== "undo"}
        >
          <span className="mr-auto whitespace-nowrap text-[13px] tabular-nums">
            {undo && (
              <>
                <NumberRoll value={undo.ids.length} /> {count(undo.ids.length)}{" "}
                {undo.action.progress?.[1]?.toLowerCase() ?? "removed"}
              </>
            )}
          </span>
          <button
            type="button"
            onClick={takeBack}
            className={`inline-flex h-7 cursor-pointer items-center rounded-full px-3 text-[12px] font-medium hover:bg-accent ${FOCUS}`}
          >
            Undo
          </button>
          {undo && (
            // The chance to undo, as a cavemio that drains; hovering holds it.
            <span
              key={undo.key}
              aria-hidden="true"
              className="absolute inset-x-0 bottom-0 h-px origin-left bg-foreground/40"
              style={{
                animation: `ui-progress ${undoFor}ms linear reverse forwards`,
                animationPlayState: holdUndo ? "paused" : "running",
              }}
              onAnimationEnd={() => commitUndo(undo)}
            />
          )}
        </div>
      </div>

      {/* Notice: one line that folds in when something went wrong. */}
      <div
        className="grid transition-[grid-template-rows] duration-300"
        style={{
          gridTemplateRows: notice ? "1fr" : "0fr",
          transitionTimingFunction: EASE,
        }}
      >
        <div className="min-w-0 overflow-hidden">
          <p className="truncate pl-1 pt-2 text-[12.5px] text-red-600 dark:text-red-400">
            {notice?.text ?? " "}
          </p>
        </div>
      </div>

      {/* Layout containment: re-laying the rows out after a sort never reaches the rest of the page. */}
      <div
        ref={gridRef}
        role="grid"
        aria-label={label}
        aria-rowcount={sorted.length + 1}
        aria-multiselectable={selectable || undefined}
        onKeyDown={onGridKey}
        className="mt-3 overflow-hidden rounded-[16px] border border-border [contain:layout_paint]"
      >
        {/* Header */}
        <div
          role="row"
          className="grid h-10 items-center border-b border-border text-[12px] text-muted-foreground @max-[34rem]:hidden"
          style={{ gridTemplateColumns: tracks }}
        >
          {selectable && (
            <span
              role="columnheader"
              className="flex items-center justify-center"
            >
              <button
                type="button"
                aria-label={
                  allState === "on" ? "Clear selection" : "Select all"
                }
                onClick={toggleAll}
                className={`flex size-8 cursor-pointer items-center justify-center rounded-[8px] hover:bg-accent ${FOCUS}`}
              >
                <Box state={allState} reduced={reduced} />
              </button>
            </span>
          )}
          {columns.map((col) => {
            const active = sort?.key === col.key;
            return (
              <span
                key={col.key}
                role="columnheader"
                aria-sort={
                  active
                    ? sort!.dir === "asc"
                      ? "ascending"
                      : "descending"
                    : col.sortable
                      ? "none"
                      : undefined
                }
                className={`min-w-0 px-1.5 ${col.align === "right" ? "text-right" : ""}`}
              >
                {col.sortable ? (
                  <button
                    type="button"
                    onClick={() => sortBy(col.key)}
                    className={`inline-flex h-7 max-w-full cursor-pointer items-center gap-1 rounded-[8px] px-1.5 transition-colors hover:bg-accent hover:text-foreground ${active ? "text-foreground" : ""} ${col.align === "right" ? "flex-row-reverse" : ""} ${FOCUS}`}
                  >
                    <span className="truncate">{col.header}</span>
                    <ArrowUp
                      className="size-3 shrink-0"
                      strokeWidth={2}
                      aria-hidden="true"
                      style={{
                        opacity: active ? 1 : 0,
                        transform: `${active && sort!.dir === "desc" ? "rotate(180deg)" : "rotate(0deg)"} scale(${active ? 1 : 0.6})`,
                        transition: reduced
                          ? "none"
                          : `transform 460ms ${THROW}, opacity 200ms ${EASE}`,
                      }}
                    />
                  </button>
                ) : (
                  <span className="block truncate px-1.5">{col.header}</span>
                )}
              </span>
            );
          })}
          {renderDetail && <span role="columnheader" aria-label="Details" />}
        </div>

        {/* Body: eases to its height; the page slides in from the side you went. */}
        <div ref={wrapRef} className="overflow-clip">
          <div ref={bodyRef} className="relative">
            {pageRows.map((row, i) => {
              const id = getRowId(row);
              return (
                <TableRow
                  key={id}
                  row={row}
                  id={id}
                  index={current * pageSize + i + 2}
                  columns={columns}
                  tracks={tracks}
                  selectable={selectable}
                  canEdit={!!onEdit}
                  hasDetail={!!renderDetail}
                  isSelected={selected.has(id)}
                  isOpen={open.has(id)}
                  delay={
                    cascade ? Math.max(0, cascade.ids.indexOf(id)) * 28 : 0
                  }
                  focusCol={cursor?.id === id ? cursor.col : null}
                  rowTab={
                    cursor
                      ? cursor.id === id && cursor.col === -1
                        ? 0
                        : -1
                      : i === 0
                        ? 0
                        : -1
                  }
                  editingKey={editing?.id === id ? editing.key : null}
                  drafts={drafts}
                  reduced={reduced}
                  name={name(row)}
                  actions={rowActions}
                />
              );
            })}

            {/* Rows that went: their own elements, folding away where they stood (see use-row-motion). */}
            <div
              ref={ghostRef}
              aria-hidden="true"
              className="pointer-events-none absolute inset-0"
            />

            {/* Nothing matches: said in the same place, the same height as a row. */}
            <div
              className="grid transition-[grid-template-rows,opacity] duration-300"
              style={{
                gridTemplateRows: pageRows.length ? "0fr" : "1fr",
                opacity: pageRows.length ? 0 : 1,
                transitionTimingFunction: EASE,
              }}
              aria-hidden={!!pageRows.length}
            >
              <div className="min-h-0 overflow-hidden">
                <p className="px-4 py-6 text-center text-[13px] text-muted-foreground">
                  <TextMorph animateWidth={false}>
                    {q
                      ? `No ${noun[1]} match “${query.trim()}”`
                      : `No ${noun[1]} yet`}
                  </TextMorph>
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Pages */}
      {pages > 1 && (
        <div className="mt-2.5 flex items-center justify-between gap-2 px-1 text-[12px] tabular-nums text-muted-foreground">
          <span className="inline-flex items-baseline">
            <NumberRoll value={from} />–<NumberRoll value={to} />
            &nbsp;of&nbsp;
            <NumberRoll value={sorted.length} />
          </span>
          <span className="flex items-center gap-0.5">
            <button
              type="button"
              aria-label="Previous page"
              disabled={current === 0}
              onClick={() => goPage(-1)}
              className={`flex size-7 cursor-pointer items-center justify-center rounded-full hover:bg-accent hover:text-foreground disabled:cursor-default disabled:opacity-40 ${FOCUS}`}
            >
              <ChevronLeft className="size-4" strokeWidth={1.75} />
            </button>
            <button
              type="button"
              aria-label="Next page"
              disabled={current >= pages - 1}
              onClick={() => goPage(1)}
              className={`flex size-7 cursor-pointer items-center justify-center rounded-full hover:bg-accent hover:text-foreground disabled:cursor-default disabled:opacity-40 ${FOCUS}`}
            >
              <ChevronRight className="size-4" strokeWidth={1.75} />
            </button>
          </span>
        </div>
      )}

      <p className="sr-only" role="status" aria-live="polite">
        {announce}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * PILL SELECT: a select that's the same surface as its pill
 *
 *   open      the pill grows into its list (size and corners
 *             ease) from the edge it's lined up with, while its
 *             label fades into the options; it opens upward when
 *             there's no room below, and long lists scroll
 *   pick      the list folds back into the pill and the label
 *             morphs to the new choice; the current option
 *             carries a drawn check
 *   keys      arrows move a highlight that glides between rows,
 *             Home and End jump, typing a few letters finds an
 *             option, Enter picks, Escape folds it back
 *
 * The list lives in a portal on the page's body, placed over
 * the pill, so a clipping toolbar, fold or scroller never cuts
 * it off; it carries the theme's colours with it. Scrolling
 * the page closes it.
 *
 * Used wherever a component needs a choice from a list; never
 * the browser's own dropdown, which can't follow the theme.
 * ───────────────────────────────────────────────────────── */

export interface PillOption {
  value: string;
  label: string;
  /** A second line in the list, e.g. a sample value. */
  description?: string;
}

export interface PillSelectProps {
  options: PillOption[];
  value: string | null | undefined;
  onValueChange: (value: string) => void;
  /** Accessible name, e.g. "Column for Email". */
  label: string;
  /** Shown while nothing is chosen. */
  placeholder?: string;
  /** What the pill shows for a choice; the option's label by default. */
  display?: (option: PillOption | undefined) => string;
  /** The pill's contents, when it needs more than text (an icon that turns). */
  renderValue?: (
    option: PillOption | undefined,
    open: boolean,
  ) => React.ReactNode;
  /** Monospace labels, for code-like values (event names, column headers). */
  mono?: boolean;
  /** Which edge of the pill the list lines up with. */
  align?: "start" | "end";
  /** The list's width; never narrower than the pill. */
  width?: number;
  /** Fill the width it's given. */
  block?: boolean;
  /** Dims the pill's text, e.g. for "Don't import". */
  muted?: boolean;
  disabled?: boolean;
  /** "sm" is the 28px pill for toolbars; "md" is 36px, the height of the other form fields. */
  size?: "sm" | "md";
  className?: string;
}

type Phase = "closed" | "opening" | "open" | "closing";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DURATION = 420;
const MAX_LIST = 280;
const PILL_SIZE = {
  sm: "h-7 px-2.5 text-[12px]",
  md: "h-9 pl-4 pr-3.5 text-[13.5px]",
};
// The theme travels with the list, so it matches the pill wherever the pill's colours were set.
const TOKENS = [
  "--background",
  "--foreground",
  "--popover",
  "--popover-foreground",
  "--border",
  "--accent",
  "--accent-foreground",
  "--primary",
  "--primary-foreground",
  "--muted",
  "--muted-foreground",
  "--ring",
];
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Chevron({ up, reduced }: { up: boolean; reduced: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3 shrink-0 text-muted-foreground"
      style={{
        transform: up ? "rotate(180deg)" : "none",
        transition: reduced ? "none" : `transform 320ms ${EASE}`,
      }}
    >
      <path
        d="M4.5 6.25 8 9.75l3.5-3.5"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function PillSelect({
  options,
  value,
  onValueChange,
  label,
  placeholder = "Choose",
  display,
  renderValue,
  mono = false,
  align = "start",
  width = 240,
  block = false,
  muted = false,
  disabled = false,
  size = "sm",
  className = "",
}: PillSelectProps) {
  const id = React.useId();
  const reduced = useReducedMotion();
  const [phase, setPhase] = React.useState<Phase>("closed");
  const [active, setActive] = React.useState(0);
  const [pill, setPill] = React.useState({ width: 0, height: 28 });
  const [panelHeight, setPanelHeight] = React.useState(0);
  const [fit, setFit] = React.useState({
    up: false,
    width,
    shift: 0,
    x: 0,
    y: 0,
    theme: {} as Record<string, string>,
  });
  const [highlight, setHighlight] = React.useState({
    top: 0,
    height: 0,
    ready: false,
  });
  const [quiet, setQuiet] = React.useState(false);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const surfaceRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const rowRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const timer = React.useRef(0);
  const typed = React.useRef({ text: "", at: 0 });
  const selected = options.find((o) => o.value === value);
  const expanded = phase === "open";
  const mounted = phase !== "closed";
  const [prevPhase, setPrevPhase] = React.useState(phase);
  if (phase !== prevPhase) {
    setPrevPhase(phase);
    if (phase === "closed") {
      setHighlight({ top: 0, height: 0, ready: false });
    }
  }
  const text = display ? display(selected) : (selected?.label ?? placeholder);

  const measureFit = () => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const rect = wrap.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const w = Math.min(Math.max(width, rect.width), vw - 24);
    // Lined up with the pill's edge, nudged back on screen.
    const shift =
      align === "start"
        ? Math.min(0, vw - 12 - (rect.left + w))
        : Math.max(0, 12 - (rect.right - w));
    const estimate =
      Math.min(
        MAX_LIST,
        options.length * (options.some((o) => o.description) ? 46 : 32),
      ) + 12;
    const vh = window.innerHeight;
    const below = vh - 8 - rect.top;
    const above = rect.bottom - 8;
    const up = below < estimate + 8 && above > below;
    // Fixed coordinates of the pill's corner the list grows from.
    const x = align === "start" ? rect.left : vw - rect.right;
    const y = up ? vh - rect.bottom : rect.top;
    const cs = getComputedStyle(wrap);
    const theme: Record<string, string> = {
      colorScheme: cs.colorScheme,
      fontFamily: cs.fontFamily,
    };
    for (const t of TOKENS) {
      const v = cs.getPropertyValue(t);
      if (v) theme[t] = v;
    }
    setFit({ up, width: w, shift, x, y, theme });
  };

  const open = () => {
    if (disabled || phase === "open" || phase === "opening") return;
    window.clearTimeout(timer.current);
    measureFit();
    setActive(
      Math.max(
        0,
        options.findIndex((o) => o.value === value),
      ),
    );
    setPhase(reduced ? "open" : "opening");
  };

  const close = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) triggerRef.current?.focus({ preventScroll: true });
      if (reduced) return setPhase("closed");
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), DURATION);
    },
    [reduced],
  );

  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  React.useLayoutEffect(() => {
    const trigger = triggerRef.current;
    if (!trigger) return;
    const measure = () =>
      setPill((p) =>
        p.width === trigger.offsetWidth && p.height === trigger.offsetHeight
          ? p
          : { width: trigger.offsetWidth, height: trigger.offsetHeight },
      );
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(trigger);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (panel) setPanelHeight(panel.offsetHeight);
  }, [mounted, options]);

  // The highlight glides to the active row, and the list scrolls to keep it in view.
  React.useLayoutEffect(() => {
    const row = rowRefs.current[active];
    const list = listRef.current;
    if (!row || !list) return;
    setHighlight((h) =>
      h.top === row.offsetTop &&
      h.height === row.offsetHeight &&
      h.ready === (h.ready || expanded)
        ? h
        : {
            top: row.offsetTop,
            height: row.offsetHeight,
            ready: h.ready || expanded,
          },
    );
    const scroller = list.parentElement;
    if (scroller && scroller.scrollHeight > scroller.clientHeight) {
      if (row.offsetTop < scroller.scrollTop)
        scroller.scrollTop = row.offsetTop - 4;
      else if (
        row.offsetTop + row.offsetHeight >
        scroller.scrollTop + scroller.clientHeight
      )
        scroller.scrollTop =
          row.offsetTop + row.offsetHeight - scroller.clientHeight + 4;
    }
  }, [active, expanded, mounted]);

  React.useEffect(() => {
    if (expanded) listRef.current?.focus({ preventScroll: true });
  }, [expanded]);

  React.useEffect(() => {
    if (!expanded) return;
    const inside = (n: Node) =>
      Boolean(wrapRef.current?.contains(n) || surfaceRef.current?.contains(n));
    const onDown = (e: PointerEvent) => {
      if (!inside(e.target as Node)) close(false);
    };
    // The list sits where the pill was; if the page moves under it, it goes at once rather than fold in the wrong place.
    const gone = () => {
      window.clearTimeout(timer.current);
      setPhase("closed");
    };
    const onScroll = (e: Event) => {
      if (!surfaceRef.current?.contains(e.target as Node)) gone();
    };
    const onResize = gone;
    document.addEventListener("pointerdown", onDown);
    window.addEventListener("scroll", onScroll, true);
    window.addEventListener("resize", onResize);
    return () => {
      document.removeEventListener("pointerdown", onDown);
      window.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("resize", onResize);
    };
  }, [expanded, close]);

  const choose = (o: PillOption) => {
    close();
    if (o.value !== value) onValueChange(o.value);
  };

  const onListKey = (e: React.KeyboardEvent) => {
    const last = options.length - 1;
    const move = (to: number) => {
      e.preventDefault();
      setActive(Math.max(0, Math.min(last, to)));
    };
    if (e.key === "ArrowDown") move(active === last ? 0 : active + 1);
    else if (e.key === "ArrowUp") move(active === 0 ? last : active - 1);
    else if (e.key === "Home") move(0);
    else if (e.key === "End") move(last);
    else if (e.key === "PageDown") move(active + 6);
    else if (e.key === "PageUp") move(active - 6);
    else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (options[active]) choose(options[active]);
    } else if (e.key === "Tab") close(false);
    else if (e.key.length === 1 && /\S/.test(e.key)) {
      // A few letters typed quickly find the option that starts with them.
      const now = performance.now();
      typed.current = {
        text:
          (now - typed.current.at < 700 ? typed.current.text : "") +
          e.key.toLowerCase(),
        at: now,
      };
      const hit = options.findIndex((o) =>
        o.label.toLowerCase().startsWith(typed.current.text),
      );
      if (hit !== -1) setActive(hit);
    }
  };

  const w = expanded ? fit.width : pill.width;
  const h = expanded ? panelHeight : pill.height;
  const listId = `${id}-list`;
  const pillText = renderValue ? null : (
    <>
      <span
        className={`min-w-0 flex-1 truncate text-left ${mono ? "font-mono text-[11.5px]" : ""} ${muted || !selected ? "text-muted-foreground" : "text-foreground"}`}
      >
        {block ? text : <TextMorph>{text}</TextMorph>}
      </span>
      <Chevron up={expanded} reduced={reduced} />
    </>
  );

  return (
    <div
      ref={wrapRef}
      className={`relative ${block ? "flex w-full min-w-0" : "inline-flex"} ${className}`}
      onKeyDown={(e) => {
        setQuiet(false);
        if (e.key === "Escape" && expanded) {
          e.preventDefault();
          e.stopPropagation();
          close();
        }
      }}
      onBlur={(e) => {
        const to = e.relatedTarget as Node | null;
        if (
          expanded &&
          document.hasFocus() &&
          !(
            to &&
            (wrapRef.current?.contains(to) || surfaceRef.current?.contains(to))
          )
        )
          close(false);
      }}
    >
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={expanded}
        aria-controls={mounted ? listId : undefined}
        aria-label={`${label}: ${selected?.label ?? placeholder}`}
        disabled={disabled}
        onClick={() => (expanded ? close() : open())}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown" || e.key === "ArrowUp") {
            e.preventDefault();
            open();
          }
        }}
        onPointerDown={() => setQuiet(true)}
        className={`inline-flex ${PILL_SIZE[size]} min-w-0 cursor-pointer items-center gap-1.5 rounded-full font-medium whitespace-nowrap shadow-[inset_0_0_0_1px_var(--border)] transition-colors duration-150 hover:bg-accent disabled:cursor-default disabled:opacity-50 disabled:hover:bg-transparent ${block ? "w-full" : ""} ${quiet ? "outline-none" : FOCUS}`}
      >
        {renderValue ? renderValue(selected, expanded) : pillText}
      </button>

      {mounted &&
        createPortal(
          <div
            ref={surfaceRef}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                e.preventDefault();
                e.stopPropagation();
                close();
              }
            }}
            onPointerDown={(e) => {
              if (!(e.target as HTMLElement).closest("[data-scroll]"))
                e.preventDefault();
              setQuiet(true);
            }}
            className="fixed z-[60] overflow-hidden bg-popover text-popover-foreground"
            style={{
              ...fit.theme,
              [fit.up ? "bottom" : "top"]: fit.y,
              [align === "start" ? "left" : "right"]:
                fit.x +
                (expanded ? (align === "start" ? fit.shift : -fit.shift) : 0),
              width: w,
              height: h,
              borderRadius: expanded ? 16 : pill.height / 2,
              // The pill's own cavemio, the whole way: it is the same surface.
              boxShadow: "inset 0 0 0 1px var(--border)",
              transition: reduced
                ? "none"
                : `width ${DURATION}ms ${EASE}, height ${DURATION}ms ${EASE}, left ${DURATION}ms ${EASE}, right ${DURATION}ms ${EASE}, border-radius ${DURATION}ms ${EASE}`,
            }}
          >
            {/* The pill's label, fading out as the surface grows and back in as it folds. */}
            <span
              aria-hidden="true"
              className={`pointer-events-none absolute inline-flex ${PILL_SIZE[size]} items-center gap-1.5 font-medium whitespace-nowrap ${fit.up ? "bottom-0" : "top-0"} ${align === "start" ? "left-0" : "right-0"}`}
              style={{
                width: pill.width,
                opacity: expanded ? 0 : 1,
                transition: reduced
                  ? "none"
                  : `opacity ${expanded ? 120 : 260}ms ${EASE} ${expanded ? 0 : 120}ms`,
              }}
            >
              {renderValue ? renderValue(selected, expanded) : pillText}
            </span>
            <div
              ref={panelRef}
              className={`absolute p-1 ${fit.up ? "bottom-0" : "top-0"} ${align === "start" ? "left-0" : "right-0"}`}
              style={{
                width: fit.width,
                opacity: expanded ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `opacity ${expanded ? 260 : 120}ms ${EASE} ${expanded ? 90 : 0}ms`,
              }}
            >
              <div
                data-scroll=""
                className="overflow-y-auto overscroll-contain"
                style={{ maxHeight: MAX_LIST }}
              >
                <div
                  ref={listRef}
                  id={listId}
                  role="listbox"
                  tabIndex={-1}
                  aria-label={label}
                  aria-activedescendant={`${id}-o${active}`}
                  onKeyDown={onListKey}
                  className="relative outline-none"
                >
                  <span
                    aria-hidden="true"
                    className="pointer-events-none absolute inset-x-0 top-0 rounded-[12px] bg-accent"
                    style={{
                      height: highlight.height,
                      transform: `translateY(${highlight.top}px)`,
                      opacity: highlight.ready ? 1 : 0,
                      transition:
                        highlight.ready && !reduced
                          ? `transform 260ms ${EASE}, height 260ms ${EASE}, opacity 200ms`
                          : "none",
                    }}
                  />
                  {options.map((o, i) => {
                    const on = o.value === value;
                    return (
                      <div
                        key={o.value}
                        ref={(el) => {
                          rowRefs.current[i] = el;
                        }}
                        id={`${id}-o${i}`}
                        role="option"
                        aria-selected={on}
                        onPointerMove={() => setActive(i)}
                        onClick={() => choose(o)}
                        className="relative flex cursor-pointer items-start gap-2 rounded-[12px] px-2.5 py-1.5"
                      >
                        <span className="min-w-0 flex-1">
                          <span
                            className={`block truncate ${mono ? "font-mono text-[12px]" : "text-[12.5px] font-medium"}`}
                          >
                            {o.label}
                          </span>
                          {o.description && (
                            <span className="mt-0.5 block truncate text-[11.5px] text-muted-foreground">
                              {o.description}
                            </span>
                          )}
                        </span>
                        <svg
                          viewBox="0 0 16 16"
                          fill="none"
                          aria-hidden="true"
                          className="mt-0.5 size-3.5 shrink-0"
                        >
                          <path
                            d="M3.5 8.5 6.5 11.5 12.5 4.5"
                            stroke="currentColor"
                            strokeWidth="1.8"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            pathLength={1}
                            strokeDasharray={1}
                            style={{
                              strokeDashoffset: on && expanded ? 0 : 1,
                              transition: reduced
                                ? "none"
                                : `stroke-dashoffset 380ms ${EASE} 160ms`,
                            }}
                          />
                        </svg>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>,
          document.body,
        )}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * ROW MOTION: rows that keep their place on screen
 *
 *   glide     after any render (a sort, a filter, new data from
 *             the server) every row that moved glides from its
 *             old place to its new one. Glides are additive, so
 *             a change that lands mid-glide adds its own offset
 *             instead of restarting anything
 *   travel    a row that sorts onto the page slides in from the
 *             side where it ranked before; one that sorts off
 *             slides out toward its new rank
 *   enter     a row that's new to the list fades in where it
 *             lands while the rows below glide clear of it
 *   leave     a row that's gone folds away where it stood. Its
 *             copy is the row's own element, detached by React
 *             and moved into a layer React never renders into,
 *             so a leaving row costs no render at all
 *   stagger   a sort can ask for the rows to set off one after
 *             another, top first
 *
 * Positions are layout offsets (transforms ignored), kept after
 * every render and whenever the list changes size (a row
 * opening its detail), so they're never stale. Rows are found
 * by data-row-id; ranks are their places in the whole sorted
 * list, not just the page.
 * ───────────────────────────────────────────────────────── */

type Seen = { top: number; height: number; el: HTMLElement };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const GLIDE = 480;

export function useRowMotion(
  container: React.RefObject<HTMLElement | null>,
  {
    reduced,
    resetKey,
    ranks,
    ghosts,
  }: {
    reduced: boolean;
    resetKey?: string | number;
    ranks: ReadonlyMap<string, number>;
    ghosts: React.RefObject<HTMLElement | null>;
  },
) {
  const seen = React.useRef(new Map<string, Seen>());
  const lastRanks = React.useRef(ranks);
  const lastKey = React.useRef(resetKey);
  const staggerNext = React.useRef(false);

  const read = React.useCallback(() => {
    const out = new Map<string, Seen>();
    container.current
      ?.querySelectorAll<HTMLElement>("[data-row-id]")
      .forEach((el) =>
        out.set(el.dataset.rowId!, {
          top: el.offsetTop,
          height: el.offsetHeight,
          el,
        }),
      );
    return out;
  }, [container]);

  /** The row React just removed, back on screen where it stood, leaving: sliding toward where it went, or folding. */
  const leave = (was: Seen, dy: number) => {
    const layer = ghosts.current;
    const el = was.el;
    if (!layer || el.isConnected) return;
    // No getAnimations() here (it flushes style for the whole page): the exit below is added last and replaces any
    // glide still on the element.
    el.removeAttribute("data-row-id");
    el.removeAttribute("tabindex");
    el.setAttribute("aria-hidden", "true");
    el.inert = true;
    Object.assign(el.style, {
      position: "absolute",
      left: "0",
      right: "0",
      top: `${was.top}px`,
      height: `${was.height}px`,
      margin: "0",
      overflow: "hidden",
    });
    layer.appendChild(el);
    const a = el.animate(
      dy
        ? [
            { transform: "translateY(0px)", opacity: 1, filter: "blur(0px)" },
            {
              transform: `translateY(${dy}px)`,
              opacity: 0,
              filter: "blur(3px)",
            },
          ]
        : [
            { opacity: 1, transform: "none", filter: "blur(0px)" },
            { opacity: 0, transform: "scale(0.985)", filter: "blur(4px)" },
          ],
      { duration: dy ? 360 : 280, easing: EASE, fill: "forwards" },
    );
    a.onfinish = a.oncancel = () => el.remove();
  };

  React.useLayoutEffect(() => {
    const el = container.current;
    if (!el) return;
    const before = seen.current;
    const after = read();
    const prevRanks = lastRanks.current;
    seen.current = after;
    lastRanks.current = ranks;
    const stagger = staggerNext.current;
    staggerNext.current = false;
    if (lastKey.current !== resetKey) {
      // A different page: the caller slides the whole body; nothing glides and nothing folds.
      lastKey.current = resetKey;
      return;
    }
    if (reduced || !before.size) return;

    // A typical row's height. Rows that come onto or leave the page only hint at the way they went (a row and a
    // quarter at most), so the list never shows holes while they travel.
    const heights = [...after.values()]
      .map((b) => b.height)
      .sort((a, b) => a - b);
    const rowH = heights[Math.floor(heights.length / 2)] ?? 48;
    const clamp = (dy: number) =>
      Math.max(-rowH * 1.25, Math.min(rowH * 1.25, dy));

    let order = 0;
    after.forEach((now, id) => {
      const row = now.el;
      const was = before.get(id);
      const delay = stagger ? Math.min(order++ * 16, 200) : 0;
      if (was) {
        const dy = was.top - now.top;
        if (Math.abs(dy) < 0.5) return;
        row.animate(
          [
            { transform: `translateY(${dy}px)`, zIndex: 1 },
            { transform: "translateY(0px)", zIndex: 1 },
          ],
          {
            duration: GLIDE,
            delay,
            easing: EASE,
            composite: "add",
            fill: "backwards",
          },
        );
        return;
      }
      const from = prevRanks.get(id);
      const to = ranks.get(id);
      if (from !== undefined && to !== undefined) {
        // It ranked somewhere off the page: it comes in from that side.
        row.animate(
          [
            {
              transform: `translateY(${clamp((from - to) * rowH)}px)`,
              opacity: 0,
              filter: "blur(3px)",
            },
            { transform: "translateY(0px)", opacity: 1, filter: "blur(0px)" },
          ],
          {
            duration: GLIDE,
            delay: delay / 2,
            easing: EASE,
            fill: "backwards",
          },
        );
        return;
      }
      row.animate(
        [
          { opacity: 0, filter: "blur(4px)" },
          { opacity: 1, filter: "blur(0px)" },
        ],
        { duration: 420, delay: 90, easing: EASE, fill: "backwards" },
      );
    });

    // Still in the list, just not on this page: its copy slides toward where it went. Gone for good: it folds.
    before.forEach((was, id) => {
      if (after.has(id)) return;
      const from = prevRanks.get(id);
      const to = ranks.get(id);
      leave(
        was,
        from !== undefined && to !== undefined
          ? clamp((to - from) * rowH) || rowH
          : 0,
      );
    });
  });

  // The list changed size without a render of ours (a detail opening by transition): keep the positions true.
  React.useEffect(() => {
    const el = container.current;
    if (!el) return;
    const observer = new ResizeObserver(() => {
      seen.current = read();
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [container, read]);

  return {
    /** The next change (a sort) sets the rows off one after another. */
    stagger: () => {
      staggerNext.current = true;
    },
  };
}

